// Func019_09_00 is a deterministically generated function
// for the repomap perf fixture; it references Func020_10_00
// so the pagerank/refs step in repomap.Build has real edges
// to walk, not an isolated file per symbol.
func Func019_09_00(a, b int) int {
	if a > b {
		return Func020_10_00(a, b) + a
	}
	return Func020_10_00(b, a) - b
}

